window.PACK_DATA = window.PACK_DATA || {};
window.PACK_DATA["n4/grammar"] = [
  {id:"g-n4-potential",type:"grammar",source:"JLPT N4",level:"N4",title:"Potentialform – können",jp:"〜える／〜られる",summary:"Die Potentialform drückt aus, dass jemand etwas tun kann. Bei う-Verben wechselt der letzte Laut in die え-Reihe + る, る-Verben bekommen られる; する wird zu できる und くる zu こられる. Das Objekt wird meist mit が markiert.",structure:["う-Verb: かく → かける","る-Verb: たべる → たべられる","する → できる, くる → こられる"],examples:[{jp:"私[わたし]は漢字[かんじ]が読[よ]めます。",de:"Ich kann Kanji lesen.",en:"I can read kanji."},{jp:"明日[あした]は早[はや]く来[こ]られますか。",de:"Können Sie morgen früh kommen?",en:"Can you come early tomorrow?"}],matches:[],tags:["konjugation","verben","können"]},
  {id:"g-n4-koto-ga-dekiru",type:"grammar",source:"JLPT N4",level:"N4",title:"ことができる – können, in der Lage sein",jp:"〜ことができる",summary:"Eine etwas förmlichere Art, „können“ zu sagen: Wörterbuchform + ことができる. Bei einem Nomen verwendet man Nomen + ができる.",structure:["Wörterbuchform + ことができる","Nomen + ができる"],examples:[{jp:"ここで写真[しゃしん]を撮[と]ることができます。",de:"Hier kann man Fotos machen.",en:"You can take photos here."},{jp:"兄[あに]はスキーができます。",de:"Mein älterer Bruder kann Ski fahren.",en:"My older brother can ski."}],matches:[],tags:["können"]},
  {id:"g-n4-passive",type:"grammar",source:"JLPT N4",level:"N4",title:"Passiv – getan werden",jp:"〜れる／〜られる",summary:"Das Passiv sagt, was dem Subjekt widerfährt; der Handelnde wird mit に markiert. Es wird oft verwendet, wenn man sich durch das Tun eines anderen gestört fühlt. う-Verben: あ-Reihe + れる, る-Verben: られる, する → される, くる → こられる.",structure:["う-Verb: よむ → よまれる","る-Verb: たべる → たべられる","Person に + Verb im Passiv"],examples:[{jp:"私[わたし]は先生[せんせい]にほめられました。",de:"Ich wurde vom Lehrer gelobt.",en:"I was praised by the teacher."},{jp:"弟[おとうと]にケーキを食[た]べられました。",de:"Mein jüngerer Bruder hat mir den Kuchen weggegessen (und das ärgert mich).",en:"My younger brother ate my cake (and I am not happy about it)."}],matches:[],tags:["konjugation","passiv"]},
  {id:"g-n4-causative",type:"grammar",source:"JLPT N4",level:"N4",title:"Kausativ – jemanden etwas tun lassen",jp:"〜せる／〜させる",summary:"Der Kausativ bedeutet, dass jemand einen anderen dazu bringt oder ihm erlaubt, etwas zu tun. う-Verben: あ-Reihe + せる, る-Verben: させる, する → させる, くる → こさせる. Kausativ in der て-Form + ください bittet um Erlaubnis: „Lassen Sie mich bitte …“.",structure:["う-Verb: いく → いかせる","る-Verb: たべる → たべさせる","Kausativ in der て-Form + ください"],examples:[{jp:"母[はは]は妹[いもうと]に野菜[やさい]を食[た]べさせます。",de:"Meine Mutter lässt meine jüngere Schwester Gemüse essen.",en:"My mother makes my younger sister eat vegetables."},{jp:"私[わたし]に払[はら]わせてください。",de:"Lassen Sie bitte mich bezahlen.",en:"Please let me pay."}],matches:[],tags:["konjugation","kausativ"]},
  {id:"g-n4-causative-passive",type:"grammar",source:"JLPT N4",level:"N4",title:"Kausativ-Passiv – etwas tun müssen, gezwungen werden",jp:"〜させられる／〜される",summary:"Das Kausativ-Passiv drückt aus, dass jemand zu etwas gezwungen wird, das er nicht tun möchte. る-Verben: させられる; う-Verben nehmen meist die verkürzte Form あ-Reihe + される (aber はなす → はなさせられる).",structure:["う-Verb: まつ → またされる","る-Verb: たべる → たべさせられる","Person に + Verb im Kausativ-Passiv"],examples:[{jp:"子[こ]どものとき、毎日[まいにち]ピアノを練習[れんしゅう]させられました。",de:"Als Kind musste ich jeden Tag Klavier üben.",en:"When I was a child, I was made to practice the piano every day."},{jp:"駅[えき]で一時間[いちじかん]も待[ま]たされました。",de:"Man hat mich am Bahnhof eine ganze Stunde warten lassen.",en:"I was kept waiting at the station for a whole hour."}],matches:[],tags:["konjugation","kausativ","passiv"]},
  {id:"g-n4-volitional",type:"grammar",source:"JLPT N4",level:"N4",title:"Volitionalform – lass uns …, ich werde …",jp:"〜よう／〜おう",summary:"Die Kurzform von 〜ましょう. Unter Freunden verwendet man sie für „lass uns …“ sowie für den eigenen Entschluss „ich mache jetzt …“. う-Verben: お-Reihe + う, る-Verben: よう, する → しよう, くる → こよう.",structure:["う-Verb: いく → いこう","る-Verb: たべる → たべよう","する → しよう, くる → こよう"],examples:[{jp:"一緒[いっしょ]に帰[かえ]ろう。",de:"Lass uns zusammen nach Hause gehen.",en:"Let's go home together."},{jp:"今日[きょう]は早[はや]く寝[ね]よう。",de:"Heute gehe ich früh ins Bett.",en:"I'll go to bed early today."}],matches:[],tags:["konjugation","volitional","vorschlag"]},
  {id:"g-n4-you-to-omou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようと思う – ich habe vor zu …",jp:"〜ようとおもう",summary:"Volitionalform + と思う sagt, was man zu tun beabsichtigt. と思います ist ein Entschluss, den man gerade eben gefasst hat, と思っています ein Plan, den man schon seit einiger Zeit hat.",structure:["Volitionalform + とおもう","Volitionalform + とおもっている"],examples:[{jp:"来年[らいねん]、日本[にほん]に行[い]こうと思[おも]っています。",de:"Ich habe vor, nächstes Jahr nach Japan zu fahren.",en:"I am thinking of going to Japan next year."}],matches:[],tags:["volitional","absicht"]},
  {id:"g-n4-imperative",type:"grammar",source:"JLPT N4",level:"N4",title:"Imperativ – tu es!",jp:"〜え／〜ろ",summary:"Ein starker, rauer Befehl. Man hört ihn in Notfällen, beim Sport, auf Schildern sowie beim Zitieren eines Befehls; im normalen Gespräch klingt er unhöflich. う-Verben: え-Reihe, る-Verben: ろ, する → しろ, くる → こい.",structure:["う-Verb: いく → いけ","る-Verb: たべる → たべろ","する → しろ, くる → こい"],examples:[{jp:"早[はや]く逃[に]げろ！",de:"Schnell, lauf weg!",en:"Run away, quick!"},{jp:"父[ちち]に「もっと勉強[べんきょう]しろ」と言[い]われました。",de:"Mein Vater hat zu mir gesagt: „Lern mehr!“",en:"My father told me to study more."}],matches:[],tags:["konjugation","befehl"]},
  {id:"g-n4-transitive-intransitive",type:"grammar",source:"JLPT N4",level:"N4",title:"Transitive und intransitive Verben",jp:"〜をあける／〜があく",summary:"Viele Verben treten als Paar auf. Das transitive Verb steht mit を und sagt, dass jemand etwas an einem Objekt tut; das intransitive Verb steht mit が und sagt, dass etwas von selbst geschieht.",structure:["Person が + Objekt を + transitives Verb","Sache が + intransitives Verb"],examples:[{jp:"私[わたし]は窓[まど]を開[あ]けました。",de:"Ich habe das Fenster geöffnet.",en:"I opened the window."},{jp:"風[かぜ]で窓[まど]が開[あ]きました。",de:"Das Fenster ist durch den Wind aufgegangen.",en:"The window opened because of the wind."}],matches:[],tags:["verben","transitivität"]},
  {id:"g-n4-ba",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ば – wenn, falls",jp:"〜ば",summary:"Die ば-Form nennt eine Bedingung: Wenn A zutrifft, folgt B. Bei Verben wechselt der letzte Laut in die え-Reihe + ば, bei い-Adjektiven wird い zu ければ, und ない wird zu なければ.",structure:["Verb: いく → いけば, たべる → たべれば","い-Adjektiv: やすい → やすければ","Verneinung: いかない → いかなければ"],examples:[{jp:"春[はる]になれば、桜[さくら]が咲[さ]きます。",de:"Wenn es Frühling wird, blühen die Kirschbäume.",en:"When spring comes, the cherry trees bloom."},{jp:"安[やす]ければ買[か]います。",de:"Wenn es billig ist, kaufe ich es.",en:"If it is cheap, I will buy it."}],matches:[],tags:["konditional"]},
  {id:"g-n4-tara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たら – wenn, falls, sobald, nachdem",jp:"〜たら",summary:"た-Form + ら. Es bedeutet „falls“ oder „wenn/nachdem“: B geschieht, sobald A abgeschlossen ist. もし am Satzanfang macht deutlich, dass ein „falls“ gemeint ist.",structure:["Verb: た-Form + ら (いったら)","い-Adjektiv: やすかったら","Nomen／な-Adjektiv + だったら"],examples:[{jp:"駅[えき]に着[つ]いたら、電話[でんわ]してください。",de:"Rufen Sie mich bitte an, wenn Sie am Bahnhof angekommen sind.",en:"Please call me when you arrive at the station."},{jp:"もし雨[あめ]が降[ふ]ったら、行[い]きません。",de:"Falls es regnet, gehe ich nicht hin.",en:"If it rains, I won't go."}],matches:[],tags:["konditional"]},
  {id:"g-n4-tara-dou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たらどうですか – wie wäre es, wenn …?",jp:"〜たらどうですか",summary:"Ein Vorschlag oder Ratschlag: „Wie wäre es, … zu tun?“. Zusammen mit einem Fragewort bittet 〜たらいいですか um Rat: „Was soll ich tun?“.",structure:["た-Form + ら + どうですか","Fragewort + た-Form + ら + いいですか"],examples:[{jp:"少[すこ]し休[やす]んだらどうですか。",de:"Wie wäre es, wenn Sie sich ein wenig ausruhen?",en:"Why don't you rest a little?"},{jp:"どこで切符[きっぷ]を買[か]ったらいいですか。",de:"Wo kaufe ich am besten die Fahrkarte?",en:"Where should I buy the ticket?"}],matches:[],tags:["konditional","rat","vorschlag"]},
  {id:"g-n4-nara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なら – wenn es so ist, dass …; was … betrifft",jp:"〜なら",summary:"なら greift etwas auf, das der Gesprächspartner gesagt hat, oder eine Situation („wenn das so ist, dann …“) und gibt dazu einen Rat oder eine Meinung. Nach einem Nomen bedeutet es auch „was … betrifft“.",structure:["Nomen + なら","Kurzform + (の)なら"],examples:[{jp:"京都[きょうと]に行[い]くなら、秋[あき]がいいですよ。",de:"Wenn Sie nach Kyoto fahren, ist der Herbst zu empfehlen.",en:"If you are going to Kyoto, autumn is a good time."},{jp:"魚[さかな]なら食[た]べられます。",de:"Fisch kann ich essen.",en:"Fish, I can eat."}],matches:[],tags:["konditional"]},
  {id:"g-n4-to-conditional",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と – immer wenn, wenn (natürliche Folge)",jp:"〜と",summary:"Kurzform im Präsens + と: Immer wenn A geschieht, folgt automatisch B. Man verwendet es für Natur, Maschinen, Wegbeschreibungen sowie Gewohnheiten; B kann keine Bitte oder Absicht sein.",structure:["Wörterbuchform／ない-Form + と","Nomen／な-Adjektiv + だ + と"],examples:[{jp:"このボタンを押[お]すと、ドアが開[あ]きます。",de:"Wenn man diesen Knopf drückt, geht die Tür auf.",en:"If you press this button, the door opens."},{jp:"右[みぎ]に曲[ま]がると、銀行[ぎんこう]があります。",de:"Wenn Sie rechts abbiegen, sehen Sie eine Bank.",en:"If you turn right, there is a bank."}],matches:[],tags:["konditional"]},
  {id:"g-n4-te-mo",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ても – auch wenn, selbst wenn",jp:"〜ても",summary:"て-Form + も: B gilt auch dann, wenn A eintritt. Zusammen mit einem Fragewort (いくら, どんなに, なに) bedeutet es „egal wie/was …“.",structure:["Verb in der て-Form + も","い-Adjektiv: 〜くても","Nomen／な-Adjektiv + でも"],examples:[{jp:"雨[あめ]が降[ふ]っても、出[で]かけます。",de:"Auch wenn es regnet, gehe ich aus.",en:"Even if it rains, I will go out."},{jp:"いくら考[かんが]えても、わかりません。",de:"Egal wie lange ich darüber nachdenke, ich verstehe es nicht.",en:"No matter how much I think about it, I don't understand."}],matches:[],tags:["konditional","einräumung","te-form"]},
  {id:"g-n4-noni-although",type:"grammar",source:"JLPT N4",level:"N4",title:"〜のに – obwohl",jp:"〜のに",summary:"のに verbindet zwei Tatsachen, die nicht zusammenpassen, und drückt Überraschung, Enttäuschung oder Beschwerde aus. Nomen und な-Adjektive stehen vor のに mit な.",structure:["Kurzform + のに","Nomen／な-Adjektiv + な + のに"],examples:[{jp:"薬[くすり]を飲[の]んだのに、熱[ねつ]が下[さ]がりません。",de:"Obwohl ich das Medikament genommen habe, sinkt das Fieber nicht.",en:"Although I took medicine, my fever is not going down."},{jp:"日曜日[にちようび]なのに、仕事[しごと]があります。",de:"Obwohl Sonntag ist, muss ich arbeiten.",en:"Even though it is Sunday, I have work."}],matches:[],tags:["einräumung"]},
  {id:"g-n4-noni-purpose",type:"grammar",source:"JLPT N4",level:"N4",title:"〜のに – um zu, für (Zweck)",jp:"〜のに",summary:"Wörterbuchform + のに sagt, wofür etwas verwendet oder benötigt wird. Danach folgen Wörter wie つかう, いい, べんりだ, ひつようだ oder かかる.",structure:["Wörterbuchform + のに + つかう／べんりだ／かかる"],examples:[{jp:"このナイフは果物[くだもの]を切[き]るのに使[つか]います。",de:"Dieses Messer benutzt man zum Obstschneiden.",en:"This knife is used for cutting fruit."},{jp:"会社[かいしゃ]に行[い]くのに一時間[いちじかん]かかります。",de:"Man braucht eine Stunde, um zur Firma zu kommen.",en:"It takes an hour to get to the office."}],matches:[],tags:["zweck"]},
  {id:"g-n4-baai-wa",type:"grammar",source:"JLPT N4",level:"N4",title:"〜場合は – im Fall, dass …; falls",jp:"〜ばあいは",summary:"Ein eher förmliches „für den Fall, dass …“, das häufig in Regeln und Anweisungen vorkommt.",structure:["Kurzform + ばあいは","Nomen + の + ばあいは","な-Adjektiv + な + ばあいは"],examples:[{jp:"雨[あめ]の場合[ばあい]は、試合[しあい]は中止[ちゅうし]です。",de:"Bei Regen fällt das Spiel aus.",en:"In case of rain, the match will be cancelled."},{jp:"遅[おく]れる場合[ばあい]は、連絡[れんらく]してください。",de:"Falls Sie sich verspäten, melden Sie sich bitte.",en:"If you are going to be late, please contact us."}],matches:[],tags:["konditional","regeln"]},
  {id:"g-n4-ba-yokatta",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ばよかった – hätte ich doch …; ich hätte … sollen",jp:"〜ばよかった",summary:"ば-Form + よかった drückt Bedauern über etwas aus, das man nicht getan hat. Die Verneinung 〜なければよかった bedauert etwas, das man getan hat.",structure:["ば-Form + よかった","ない-Form: 〜なければ + よかった"],examples:[{jp:"もっと早[はや]く起[お]きればよかった。",de:"Ich hätte früher aufstehen sollen.",en:"I should have got up earlier."},{jp:"あんなに食[た]べなければよかったです。",de:"Hätte ich doch nicht so viel gegessen.",en:"I wish I had not eaten that much."}],matches:[],tags:["konditional","bedauern"]},
  {id:"g-n4-to-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜といいですね – hoffentlich",jp:"〜といい",summary:"Kurzform im Präsens + といい drückt eine Hoffnung aus. 〜といいですね ist ein Wunsch für jemand anderen, 〜といいんですが ein Wunsch für sich selbst.",structure:["Kurzform im Präsens + といいですね","Kurzform im Präsens + といいんですが"],examples:[{jp:"明日[あした]、晴[は]れるといいですね。",de:"Hoffentlich wird es morgen sonnig.",en:"I hope it will be sunny tomorrow."},{jp:"試験[しけん]に合格[ごうかく]できるといいんですが。",de:"Hoffentlich bestehe ich die Prüfung.",en:"I hope I can pass the exam."}],matches:[],tags:["wunsch"]},
  {id:"g-n4-te-miru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てみる – etwas ausprobieren",jp:"〜てみる",summary:"て-Form + みる bedeutet, etwas zu tun, um zu sehen, wie es ist.",structure:["て-Form + みる"],examples:[{jp:"この靴[くつ]をはいてみてもいいですか。",de:"Darf ich diese Schuhe anprobieren?",en:"May I try these shoes on?"},{jp:"日本[にほん]の料理[りょうり]を作[つく]ってみました。",de:"Ich habe versucht, japanisches Essen zu kochen.",en:"I tried making Japanese food."}],matches:[],tags:["te-form"]},
  {id:"g-n4-te-oku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ておく – etwas im Voraus tun; etwas so lassen",jp:"〜ておく",summary:"て-Form + おく bedeutet, etwas vorab zur Vorbereitung zu tun oder etwas in seinem jetzigen Zustand zu belassen. In der Umgangssprache wird ておく zu とく.",structure:["て-Form + おく","Umgangssprachlich: 〜とく／〜どく"],examples:[{jp:"旅行[りょこう]の前[まえ]に、ホテルを予約[よやく]しておきます。",de:"Vor der Reise buche ich schon einmal ein Hotel.",en:"I will book a hotel before the trip."},{jp:"窓[まど]は開[あ]けておいてください。",de:"Lassen Sie das Fenster bitte offen.",en:"Please leave the window open."}],matches:[],tags:["te-form","vorbereitung"]},
  {id:"g-n4-te-shimau",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てしまう／〜ちゃう – fertig machen; aus Versehen tun",jp:"〜てしまう／〜ちゃう",summary:"て-Form + しまう bedeutet, etwas vollständig zu erledigen, oder dass etwas geschehen ist, das man bedauert. In der Umgangssprache wird てしまう zu ちゃう und でしまう zu じゃう.",structure:["て-Form + しまう","Umgangssprachlich: 〜ちゃう／〜じゃう"],examples:[{jp:"宿題[しゅくだい]を全部[ぜんぶ]やってしまいました。",de:"Ich habe die Hausaufgaben komplett erledigt.",en:"I have finished all my homework."},{jp:"電車[でんしゃ]に傘[かさ]を忘[わす]れちゃった。",de:"Ich habe meinen Schirm im Zug vergessen (so ein Mist).",en:"I left my umbrella on the train (oh no)."}],matches:[],tags:["te-form","bedauern"]},
  {id:"g-n4-te-aru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てある – ist getan worden (und noch immer so)",jp:"〜てある",summary:"て-Form eines transitiven Verbs + ある beschreibt einen Zustand, der das Ergebnis einer absichtlichen Handlung ist. Die Sache wird mit が markiert.",structure:["Sache が + transitives Verb in der て-Form + ある"],examples:[{jp:"黒板[こくばん]に名前[なまえ]が書[か]いてあります。",de:"An der Tafel steht ein Name geschrieben.",en:"A name is written on the blackboard."},{jp:"飲[の]み物[もの]はもう買[か]ってあります。",de:"Die Getränke sind schon gekauft.",en:"The drinks have already been bought."}],matches:[],tags:["te-form","zustand"]},
  {id:"g-n4-te-iku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていく – etwas tun und gehen; sich weiter verändern",jp:"〜ていく",summary:"て-Form + いく bedeutet, etwas zu tun und dann zu gehen, oder dass eine Veränderung oder Handlung von jetzt an weitergeht – vom Sprecher weg.",structure:["て-Form + いく"],examples:[{jp:"パーティーにワインを持[も]っていきます。",de:"Ich bringe Wein zur Party mit.",en:"I will take wine to the party."},{jp:"これから寒[さむ]くなっていきます。",de:"Von jetzt an wird es immer kälter.",en:"It will keep getting colder from now on."}],matches:[],tags:["te-form","richtung"]},
  {id:"g-n4-te-kuru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくる – etwas tun und zurückkommen; geworden sein",jp:"〜てくる",summary:"て-Form + くる bedeutet, etwas zu tun und (zurück)zukommen, oder dass eine Veränderung bis jetzt angedauert hat – auf den Sprecher zu.",structure:["て-Form + くる"],examples:[{jp:"ちょっとジュースを買[か]ってきます。",de:"Ich gehe kurz Saft kaufen (und komme gleich wieder).",en:"I will just go and buy some juice (and come back)."},{jp:"日本語[にほんご]がおもしろくなってきました。",de:"Japanisch ist für mich allmählich interessant geworden.",en:"Japanese has become interesting to me."}],matches:[],tags:["te-form","richtung"]},
  {id:"g-n4-te-ageru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てあげる – etwas für jemanden tun",jp:"〜てあげる／〜てやる",summary:"て-Form + あげる sagt, dass man selbst (oder jemand) einem anderen einen Gefallen tut. てやる verwendet man gegenüber jüngeren Familienmitgliedern, Tieren und Pflanzen.",structure:["Person に + て-Form + あげる","て-Form + やる (gegenüber Rangniedrigeren)"],examples:[{jp:"友[とも]だちに傘[かさ]を貸[か]してあげました。",de:"Ich habe meinem Freund einen Schirm geliehen.",en:"I lent my friend an umbrella."},{jp:"毎朝[まいあさ]、犬[いぬ]を散歩[さんぽ]に連[つ]れていってやります。",de:"Jeden Morgen gehe ich mit dem Hund spazieren.",en:"Every morning I take the dog for a walk."}],matches:[],tags:["te-form","geben"]},
  {id:"g-n4-te-kureru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくれる – jemand tut etwas für mich",jp:"〜てくれる",summary:"て-Form + くれる sagt, dass jemand einem selbst oder der eigenen Familie einen Gefallen tut. Der Handelnde ist das Subjekt.",structure:["Person が + て-Form + くれる"],examples:[{jp:"友[とも]だちが駅[えき]まで送[おく]ってくれました。",de:"Mein Freund hat mich zum Bahnhof gebracht.",en:"My friend took me to the station."}],matches:[],tags:["te-form","geben"]},
  {id:"g-n4-te-morau",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てもらう – sich etwas von jemandem tun lassen",jp:"〜てもらう",summary:"て-Form + もらう sagt, dass man einen Gefallen erhält: Man bringt jemanden dazu, etwas für einen zu tun. Der Handelnde wird mit に markiert.",structure:["Person に + て-Form + もらう"],examples:[{jp:"先生[せんせい]に作文[さくぶん]を直[なお]してもらいました。",de:"Ich habe meinen Aufsatz vom Lehrer korrigieren lassen.",en:"I had my teacher correct my essay."}],matches:[],tags:["te-form","bekommen"]},
  {id:"g-n4-te-hoshii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てほしい – ich möchte, dass du …",jp:"〜てほしい",summary:"て-Form + ほしい sagt, dass man möchte, dass eine andere Person etwas tut. Diese Person wird mit に markiert. „Ich möchte, dass du nicht …“ heißt 〜ないでほしい.",structure:["Person に + て-Form + ほしい","ない-Form + で + ほしい"],examples:[{jp:"両親[りょうしん]に元気[げんき]でいてほしいです。",de:"Ich wünsche mir, dass meine Eltern gesund bleiben.",en:"I want my parents to stay healthy."},{jp:"ここでたばこを吸[す]わないでほしいです。",de:"Ich möchte, dass hier nicht geraucht wird.",en:"I would like you not to smoke here."}],matches:[],tags:["te-form","wunsch"]},
  {id:"g-n4-te-itadakemasen-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていただけませんか – könnten Sie bitte …?",jp:"〜ていただけませんか",summary:"Eine sehr höfliche Bitte, höflicher als 〜てください und 〜てくれませんか.",structure:["て-Form + いただけませんか"],examples:[{jp:"もう一度[いちど]説明[せつめい]していただけませんか。",de:"Könnten Sie es bitte noch einmal erklären?",en:"Could you please explain it once more?"}],matches:[],tags:["te-form","bitte","keigo"]},
  {id:"g-n4-te-sumimasen",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てすみません – Entschuldigung, dass …",jp:"〜てすみません",summary:"Die て-Form nennt den Grund für eine Entschuldigung. „Entschuldigung, dass ich nicht …“ heißt 〜なくてすみません.",structure:["て-Form + すみません","ない-Form: 〜なくて + すみません"],examples:[{jp:"遅[おそ]くなってすみません。",de:"Entschuldigen Sie die Verspätung.",en:"I am sorry for being late."}],matches:[],tags:["te-form","entschuldigung"]},
  {id:"g-n4-te-yokatta",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てよかった – ich bin froh, dass …",jp:"〜てよかった",summary:"て-Form + よかった sagt, dass man froh ist, dass etwas geschehen ist oder getan wurde.",structure:["て-Form + よかった","ない-Form: 〜なくて + よかった"],examples:[{jp:"日本語[にほんご]を勉強[べんきょう]してよかったです。",de:"Ich bin froh, dass ich Japanisch gelernt habe.",en:"I am glad I studied Japanese."}],matches:[],tags:["te-form","gefühl"]},
  {id:"g-n4-te-kurete-arigatou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜てくれてありがとう – danke, dass du …",jp:"〜てくれてありがとう",summary:"Damit bedankt man sich bei jemandem für das, was er für einen getan hat. Zu Höhergestellten sagt man 〜てくださってありがとうございます.",structure:["て-Form + くれてありがとう","Höflich: て-Form + くださってありがとうございます"],examples:[{jp:"手伝[てつだ]ってくれてありがとう。",de:"Danke, dass du mir geholfen hast.",en:"Thank you for helping me."}],matches:[],tags:["te-form","dank"]},
  {id:"g-n4-te-reason",type:"grammar",source:"JLPT N4",level:"N4",title:"〜て／〜で – und deshalb, weil",jp:"〜て／〜で",summary:"Die て-Form kann den Grund oder die Ursache für das Folgende angeben, typischerweise für ein Gefühl oder etwas, das man nicht beeinflussen kann. Nomen und な-Adjektive stehen mit で, die Verneinung lautet 〜なくて.",structure:["Verb in der て-Form／い-Adjektiv 〜くて + Folge","Nomen／な-Adjektiv + で + Folge"],examples:[{jp:"ニュースを聞[き]いて、びっくりしました。",de:"Als ich die Nachricht hörte, war ich überrascht.",en:"I was surprised to hear the news."},{jp:"地震[じしん]で電車[でんしゃ]が止[と]まりました。",de:"Wegen des Erdbebens blieben die Züge stehen.",en:"The trains stopped because of the earthquake."}],matches:[],tags:["te-form","grund"]},
  {id:"g-n4-te-ita",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ていた – war gerade dabei zu tun",jp:"〜ていた",summary:"Die Vergangenheit von 〜ている: eine Handlung, die zu einem Zeitpunkt in der Vergangenheit gerade im Gang war, oder ein Zustand, der damals andauerte.",structure:["て-Form + いた／いました"],examples:[{jp:"電話[でんわ]が鳴[な]ったとき、シャワーを浴[あ]びていました。",de:"Als das Telefon klingelte, war ich gerade unter der Dusche.",en:"When the phone rang, I was taking a shower."}],matches:[],tags:["te-form","vergangenheit","verlauf"]},
  {id:"g-n4-ru-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜るところだ – gerade im Begriff sein zu tun",jp:"〜るところだ",summary:"Wörterbuchform + ところだ sagt, dass man gerade im Begriff ist, mit etwas anzufangen.",structure:["Wörterbuchform + ところだ"],examples:[{jp:"今[いま]から出[で]かけるところです。",de:"Ich will gerade aus dem Haus gehen.",en:"I am just about to go out."}],matches:[],tags:["tokoro","zeitpunkt"]},
  {id:"g-n4-te-iru-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ているところだ – gerade mitten dabei sein",jp:"〜ているところだ",summary:"ている + ところだ betont, dass die Handlung genau in diesem Moment abläuft.",structure:["て-Form + いる + ところだ"],examples:[{jp:"今[いま]、晩[ばん]ご飯[はん]を作[つく]っているところです。",de:"Ich bin gerade dabei, das Abendessen zu kochen.",en:"I am in the middle of making dinner right now."}],matches:[],tags:["tokoro","zeitpunkt","verlauf"]},
  {id:"g-n4-ta-tokoro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たところだ – gerade eben getan haben",jp:"〜たところだ",summary:"た-Form + ところだ sagt, dass etwas erst vor einem Augenblick abgeschlossen wurde.",structure:["た-Form + ところだ"],examples:[{jp:"ちょうど今[いま]、家[いえ]に帰[かえ]ったところです。",de:"Ich bin gerade eben erst nach Hause gekommen.",en:"I have just got home this very moment."}],matches:[],tags:["tokoro","zeitpunkt"]},
  {id:"g-n4-ta-bakari",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たばかり – gerade erst getan",jp:"〜たばかり",summary:"た-Form + ばかり sagt, dass seit einem Ereignis noch nicht viel Zeit vergangen ist – nach dem Empfinden des Sprechers. Es kann Minuten oder Monate her sein.",structure:["た-Form + ばかりだ","た-Form + ばかりの + Nomen"],examples:[{jp:"先月[せんげつ]日本[にほん]に来[き]たばかりです。",de:"Ich bin erst letzten Monat nach Japan gekommen.",en:"I only came to Japan last month."},{jp:"さっき食[た]べたばかりなので、おなかがいっぱいです。",de:"Ich habe gerade erst gegessen, deshalb bin ich satt.",en:"I have just eaten, so I am full."}],matches:[],tags:["zeitpunkt"]},
  {id:"g-n4-hajimeru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜始める – anfangen zu",jp:"〜はじめる",summary:"Verbstamm (ます-Form ohne ます) + はじめる bedeutet, mit etwas anzufangen.",structure:["Verbstamm + はじめる"],examples:[{jp:"去年[きょねん]からピアノを習[なら]い始[はじ]めました。",de:"Ich habe letztes Jahr angefangen, Klavier zu lernen.",en:"I started learning the piano last year."}],matches:[],tags:["verbstamm","verbkompositum"]},
  {id:"g-n4-owaru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜終わる – etwas zu Ende tun",jp:"〜おわる",summary:"Verbstamm + おわる bedeutet, etwas zu Ende zu bringen.",structure:["Verbstamm + おわる"],examples:[{jp:"その本[ほん]はもう読[よ]み終[お]わりました。",de:"Das Buch habe ich schon zu Ende gelesen.",en:"I have already finished reading that book."}],matches:[],tags:["verbstamm","verbkompositum"]},
  {id:"g-n4-tsuzukeru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜続ける – etwas weiter tun",jp:"〜つづける",summary:"Verbstamm + つづける bedeutet, etwas immer weiter zu tun.",structure:["Verbstamm + つづける"],examples:[{jp:"三時間[さんじかん]も歩[ある]き続[つづ]けました。",de:"Wir sind ganze drei Stunden lang weitergelaufen.",en:"We kept walking for three whole hours."}],matches:[],tags:["verbstamm","verbkompositum"]},
  {id:"g-n4-dasu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜出す – plötzlich anfangen zu",jp:"〜だす",summary:"Verbstamm + だす sagt, dass etwas plötzlich und unerwartet beginnt.",structure:["Verbstamm + だす"],examples:[{jp:"急[きゅう]に雨[あめ]が降[ふ]り出[だ]しました。",de:"Plötzlich fing es an zu regnen.",en:"Suddenly it started to rain."},{jp:"赤[あか]ちゃんが泣[な]き出[だ]しました。",de:"Das Baby brach in Tränen aus.",en:"The baby burst into tears."}],matches:[],tags:["verbstamm","verbkompositum"]},
  {id:"g-n4-yasui",type:"grammar",source:"JLPT N4",level:"N4",title:"〜やすい – leicht zu tun",jp:"〜やすい",summary:"Verbstamm + やすい bedeutet, dass etwas leicht zu tun ist oder leicht passiert. Das Ergebnis ist ein い-Adjektiv.",structure:["Verbstamm + やすい"],examples:[{jp:"このペンは書[か]きやすいです。",de:"Mit diesem Stift lässt es sich gut schreiben.",en:"This pen is easy to write with."}],matches:[],tags:["verbstamm","adjektive"]},
  {id:"g-n4-nikui",type:"grammar",source:"JLPT N4",level:"N4",title:"〜にくい – schwer zu tun",jp:"〜にくい",summary:"Verbstamm + にくい bedeutet, dass etwas schwer zu tun ist oder nicht so leicht passiert. Das Ergebnis ist ein い-Adjektiv.",structure:["Verbstamm + にくい"],examples:[{jp:"この薬[くすり]は苦[にが]くて飲[の]みにくいです。",de:"Dieses Medikament ist bitter und schwer einzunehmen.",en:"This medicine is bitter and hard to take."}],matches:[],tags:["verbstamm","adjektive"]},
  {id:"g-n4-zurai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜づらい – schwer zu tun (es fühlt sich unangenehm an)",jp:"〜づらい",summary:"Verbstamm + づらい bedeutet ebenfalls „schwer zu tun“, aber die Schwierigkeit wird vom Sprecher empfunden: Es ist körperlich oder seelisch unangenehm.",structure:["Verbstamm + づらい"],examples:[{jp:"この靴[くつ]は歩[ある]きづらいです。",de:"In diesen Schuhen läuft es sich schlecht.",en:"These shoes are hard to walk in."},{jp:"先生[せんせい]には言[い]いづらいことです。",de:"Das ist etwas, das man dem Lehrer nur schwer sagen kann.",en:"It is something that is hard to tell the teacher."}],matches:[],tags:["verbstamm","adjektive"]},
  {id:"g-n4-nagara",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ながら – während, beim Tun",jp:"〜ながら",summary:"Verbstamm + ながら: Eine Person tut zwei Dinge gleichzeitig. Die Haupthandlung steht am Schluss.",structure:["Verbstamm + ながら + Haupthandlung"],examples:[{jp:"音楽[おんがく]を聞[き]きながら勉強[べんきょう]します。",de:"Ich lerne, während ich Musik höre.",en:"I study while listening to music."}],matches:[],tags:["verbstamm","zeit"]},
  {id:"g-n4-nasai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なさい – tu … (Aufforderung)",jp:"〜なさい",summary:"Verbstamm + なさい ist eine bestimmte, aber nicht unhöfliche Aufforderung, wie sie Eltern gegenüber Kindern, Lehrer gegenüber Schülern verwenden und wie sie in Prüfungsanweisungen steht.",structure:["Verbstamm + なさい"],examples:[{jp:"早[はや]く起[お]きなさい。",de:"Steh schnell auf.",en:"Get up quickly."},{jp:"野菜[やさい]も食[た]べなさい。",de:"Iss auch dein Gemüse.",en:"Eat your vegetables, too."}],matches:[],tags:["verbstamm","befehl"]},
  {id:"g-n4-kata",type:"grammar",source:"JLPT N4",level:"N4",title:"〜方 – wie man etwas tut, Art und Weise",jp:"〜かた",summary:"Verbstamm + かた bildet ein Nomen in der Bedeutung „die Art, etwas zu tun“. Das Objekt des Verbs wird mit の angeschlossen.",structure:["Verbstamm + かた","Nomen の + Verbstamm + かた"],examples:[{jp:"この漢字[かんじ]の読[よ]み方[かた]を教[おし]えてください。",de:"Sagen Sie mir bitte, wie man dieses Kanji liest.",en:"Please tell me how to read this kanji."}],matches:[],tags:["verbstamm","nomen"]},
  {id:"g-n4-tagaru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜たがる – (jemand anderes) möchte",jp:"〜たがる",summary:"〜たい gilt nur für die eigenen Wünsche. Für eine andere Person verwendet man Verbstamm + たがる, meist als 〜たがっている: Er oder sie lässt erkennen, dass er oder sie etwas tun möchte.",structure:["Verbstamm + たがる／たがっている"],examples:[{jp:"子[こ]どもは外[そと]で遊[あそ]びたがっています。",de:"Das Kind möchte draußen spielen.",en:"The child wants to play outside."}],matches:[],tags:["verbstamm","wunsch"]},
  {id:"g-n4-garu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がる – (jemand anderes) empfindet, lässt erkennen",jp:"〜がる／〜がっている",summary:"Gefühlsadjektive (ほしい, こわい, さびしい …) beschreiben nur die eigenen Gefühle. Für eine andere Person ersetzt man い durch がる: Er oder sie verhält sich so, als empfinde er oder sie das. Das Ergebnis ist ein う-Verb, das を verlangt.",structure:["い-Adjektiv ohne い + がる","な-Adjektiv + がる"],examples:[{jp:"妹[いもうと]は新[あたら]しいかばんをほしがっています。",de:"Meine jüngere Schwester wünscht sich eine neue Tasche.",en:"My younger sister wants a new bag."},{jp:"弟[おとうと]は犬[いぬ]をこわがります。",de:"Mein jüngerer Bruder hat Angst vor Hunden.",en:"My younger brother is afraid of dogs."}],matches:[],tags:["adjektive","gefühl"]},
  {id:"g-n4-sou-looks",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうだ – sieht aus wie, scheint (dem Augenschein nach)",jp:"〜そうだ",summary:"Verbstamm oder Adjektivstamm + そうだ gibt den eigenen Eindruck davon wieder, wie etwas aussieht: „es sieht … aus“, „es wird gleich …“. いい wird zu よさそう, ない zu なさそう. Nicht verwechseln mit Kurzform + そうだ („ich habe gehört“).",structure:["Verbstamm + そうだ","い-Adjektiv ohne い + そうだ","な-Adjektiv + そうだ"],examples:[{jp:"このケーキはおいしそうです。",de:"Dieser Kuchen sieht lecker aus.",en:"This cake looks delicious."},{jp:"雨[あめ]が降[ふ]りそうです。",de:"Es sieht nach Regen aus.",en:"It looks like it is going to rain."}],matches:[],tags:["anschein","vermutung"]},
  {id:"g-n4-sou-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうに／〜そうな – … aussehend, auf … wirkende Weise",jp:"〜そうに／〜そうな",summary:"Das そう für „sieht aus wie“ verhält sich wie ein な-Adjektiv: そうな steht vor einem Nomen, そうに vor einem Verb.",structure:["Stamm + そうな + Nomen","Stamm + そうに + Verb"],examples:[{jp:"子[こ]どもたちが楽[たの]しそうに遊[あそ]んでいます。",de:"Die Kinder spielen vergnügt.",en:"The children are playing happily."},{jp:"高[たか]そうな時計[とけい]ですね。",de:"Das ist ja eine teuer aussehende Uhr.",en:"That is an expensive-looking watch."}],matches:[],tags:["anschein"]},
  {id:"g-n4-sou-da-hearsay",type:"grammar",source:"JLPT N4",level:"N4",title:"〜そうだ – ich habe gehört, dass",jp:"〜そうだ",summary:"Kurzform + そうだ gibt eine Information weiter, die man gehört oder gelesen hat. Die Quelle nennt man mit 〜によると. Nomen und な-Adjektive behalten だ: 〜だそうだ.",structure:["Kurzform + そうだ","Nomen／な-Adjektiv + だ + そうだ","Quelle + によると"],examples:[{jp:"天気予報[てんきよほう]によると、明日[あした]は雪[ゆき]が降[ふ]るそうです。",de:"Laut Wetterbericht soll es morgen schneien.",en:"According to the weather forecast, it will snow tomorrow."},{jp:"田中[たなか]さんは来月[らいげつ]結婚[けっこん]するそうです。",de:"Ich habe gehört, dass Herr Tanaka nächsten Monat heiratet.",en:"I heard that Mr. Tanaka is getting married next month."}],matches:[],tags:["hörensagen"]},
  {id:"g-n4-you-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようだ – es scheint, dass",jp:"〜ようだ",summary:"Eine Einschätzung auf der Grundlage dessen, was man selbst gesehen, gehört oder gespürt hat: „es scheint, dass …“. Es ist förmlicher als みたいだ.",structure:["Kurzform + ようだ","Nomen + の + ようだ","な-Adjektiv + な + ようだ"],examples:[{jp:"だれか来[き]たようです。",de:"Es scheint jemand gekommen zu sein.",en:"It seems that someone has come."},{jp:"田中[たなか]さんは留守[るす]のようです。",de:"Herr Tanaka scheint nicht da zu sein.",en:"Mr. Tanaka seems to be out."}],matches:[],tags:["vermutung"]},
  {id:"g-n4-you-na",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ような／〜ように – wie, so wie",jp:"〜ような／〜ように",summary:"Vergleicht etwas mit etwas Ähnlichem oder nennt ein Beispiel. ような steht vor einem Nomen, ように vor einem Verb oder Adjektiv.",structure:["Nomen + の + ような + Nomen","Nomen + の + ように + Verb／Adjektiv","Kurzform + ように"],examples:[{jp:"彼[かれ]は子[こ]どものように笑[わら]います。",de:"Er lacht wie ein Kind.",en:"He laughs like a child."},{jp:"東京[とうきょう]のような大[おお]きい町[まち]に住[す]みたいです。",de:"Ich möchte in einer großen Stadt wie Tokio wohnen.",en:"I want to live in a big city like Tokyo."}],matches:[],tags:["vergleich"]},
  {id:"g-n4-mitai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜みたいだ – sieht aus wie, scheint (umgangssprachlich)",jp:"〜みたいだ",summary:"Die umgangssprachliche Variante von ようだ: eine Vermutung aufgrund dessen, was man wahrnimmt, oder ein Vergleich „ist wie …“. Es folgt direkt auf die Kurzform, ohne だ, の oder な.",structure:["Kurzform + みたいだ","Nomen／な-Adjektiv + みたいだ"],examples:[{jp:"風邪[かぜ]をひいたみたいです。",de:"Ich habe mich anscheinend erkältet.",en:"It seems I have caught a cold."},{jp:"あの雲[くも]は魚[さかな]みたいだ。",de:"Die Wolke dort sieht aus wie ein Fisch.",en:"That cloud looks like a fish."}],matches:[],tags:["vermutung","vergleich","informell"]},
  {id:"g-n4-mitai-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜みたいな／〜みたいに – wie (umgangssprachlich)",jp:"〜みたいな／〜みたいに",summary:"みたい verhält sich wie ein な-Adjektiv: みたいな vor einem Nomen, みたいに vor einem Verb oder Adjektiv. Es ist die umgangssprachliche Variante von のような／のように.",structure:["Nomen + みたいな + Nomen","Nomen + みたいに + Verb／Adjektiv"],examples:[{jp:"今日[きょう]は夏[なつ]みたいに暑[あつ]いです。",de:"Heute ist es heiß wie im Sommer.",en:"Today is as hot as summer."},{jp:"私[わたし]も姉[あね]みたいな人[ひと]になりたいです。",de:"Auch ich möchte ein Mensch wie meine ältere Schwester werden.",en:"I want to become a person like my older sister, too."}],matches:[],tags:["vergleich","informell"]},
  {id:"g-n4-rashii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜らしい – anscheinend; typisch für",jp:"〜らしい",summary:"Kurzform + らしい ist eine Vermutung auf der Grundlage dessen, was man gehört oder gelesen hat: „anscheinend …“. Nomen + らしい kann auch „ganz wie ein echter …“, „typisch für …“ bedeuten. らしい selbst ist ein い-Adjektiv.",structure:["Kurzform + らしい","Nomen／な-Adjektiv + らしい"],examples:[{jp:"あの店[みせ]のラーメンはおいしいらしいです。",de:"Die Ramen in dem Laden dort sollen lecker sein.",en:"Apparently the ramen at that shop is good."},{jp:"今日[きょう]は春[はる]らしい天気[てんき]ですね。",de:"Heute ist richtig frühlingshaftes Wetter, nicht wahr?",en:"Today the weather is really spring-like."}],matches:[],tags:["vermutung","hörensagen"]},
  {id:"g-n4-kamoshirenai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かもしれない – vielleicht, könnte sein",jp:"〜かもしれない",summary:"Kurzform + かもしれない sagt, dass etwas möglich ist, man sich aber nicht sicher ist. Bei Nomen und な-Adjektiven entfällt だ. Die höfliche Form lautet かもしれません, die umgangssprachliche Verkürzung かも.",structure:["Kurzform + かもしれない","Nomen／な-Adjektiv + かもしれない"],examples:[{jp:"午後[ごご]は雨[あめ]が降[ふ]るかもしれません。",de:"Am Nachmittag regnet es vielleicht.",en:"It might rain in the afternoon."}],matches:[],tags:["vermutung"]},
  {id:"g-n4-hazu-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜はずだ – müsste, sollte eigentlich",jp:"〜はずだ",summary:"はずだ sagt, dass man sich ziemlich sicher ist, weil man einen guten Grund dafür hat: „es müsste so sein“.",structure:["Kurzform + はずだ","Nomen + の + はずだ","な-Adjektiv + な + はずだ"],examples:[{jp:"荷物[にもつ]は明日[あした]届[とど]くはずです。",de:"Das Paket müsste morgen ankommen.",en:"The parcel should arrive tomorrow."},{jp:"今日[きょう]は日曜日[にちようび]だから、銀行[ぎんこう]は休[やす]みのはずです。",de:"Heute ist Sonntag, also müsste die Bank geschlossen sein.",en:"Today is Sunday, so the bank should be closed."}],matches:[],tags:["vermutung","erwartung"]},
  {id:"g-n4-hazu-ga-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜はずがない – kann nicht sein",jp:"〜はずがない",summary:"Sagt, dass man sicher ist, dass etwas unmöglich ist: „es ist ausgeschlossen, dass …“.",structure:["Kurzform + はずがない","Nomen + の + はずがない","な-Adjektiv + な + はずがない"],examples:[{jp:"あの人[ひと]がそんなことを言[い]うはずがありません。",de:"Diese Person würde so etwas niemals sagen.",en:"That person would never say such a thing."}],matches:[],tags:["vermutung","verneinung"]},
  {id:"g-n4-ni-mieru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜に見える – aussehen, wirken",jp:"〜にみえる",summary:"Sagt, wie etwas für das Auge aussieht. Nomen und な-Adjektive stehen mit に, bei い-Adjektiven wird い zu く.",structure:["Nomen／な-Adjektiv + に + みえる","い-Adjektiv: 〜く + みえる"],examples:[{jp:"あの雲[くも]は犬[いぬ]に見[み]えます。",de:"Die Wolke dort sieht aus wie ein Hund.",en:"That cloud looks like a dog."},{jp:"母[はは]は年[とし]より若[わか]く見[み]えます。",de:"Meine Mutter sieht jünger aus, als sie ist.",en:"My mother looks younger than her age."}],matches:[],tags:["anschein"]},
  {id:"g-n4-ga-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がする – es riecht, klingt, schmeckt, fühlt sich an",jp:"〜がする",summary:"Ein Nomen für etwas, das man mit den Sinnen wahrnimmt (におい, おと, こえ, あじ, かんじ), + がする sagt, dass man es bemerkt.",structure:["におい／おと／こえ／あじ + がする"],examples:[{jp:"台所[だいどころ]からいいにおいがします。",de:"Aus der Küche riecht es gut.",en:"There is a nice smell coming from the kitchen."},{jp:"外[そと]で変[へん]な音[おと]がしました。",de:"Draußen war ein seltsames Geräusch zu hören.",en:"There was a strange sound outside."}],matches:[],tags:["sinne"]},
  {id:"g-n4-to-kiita",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と聞いた – ich habe gehört, dass",jp:"〜ときいた",summary:"Kurzform + と聞きました gibt wieder, was man gehört hat. Die Person, von der man es gehört hat, wird mit から oder に markiert.",structure:["Kurzform + ときいた","Person から／に + … + ときいた"],examples:[{jp:"友[とも]だちから、あの映画[えいが]はおもしろいと聞[き]きました。",de:"Ich habe von einem Freund gehört, dass der Film interessant ist.",en:"I heard from a friend that that movie is interesting."}],matches:[],tags:["hörensagen","zitat"]},
  {id:"g-n4-to-iwarete-iru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と言われている – man sagt, dass",jp:"〜といわれている",summary:"Gibt eine allgemeine Meinung oder allgemein Bekanntes wieder, ohne zu nennen, wer es sagt.",structure:["Kurzform + といわれている"],examples:[{jp:"日本語[にほんご]は難[むずか]しいと言[い]われています。",de:"Man sagt, Japanisch sei schwierig.",en:"It is said that Japanese is difficult."}],matches:[],tags:["hörensagen","passiv","zitat"]},
  {id:"g-n4-to-itte-mo-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜と言ってもいい – man könnte sagen, dass",jp:"〜といってもいい",summary:"Drückt das eigene Urteil vorsichtig aus: „man kann durchaus sagen, dass …“.",structure:["Kurzform + といってもいい","Nomen + (だ) + といってもいい"],examples:[{jp:"ここは日本[にほん]で一番[いちばん]きれいな町[まち]だと言[い]ってもいいです。",de:"Man kann sagen, dass dies die schönste Stadt Japans ist.",en:"You could say this is the most beautiful town in Japan."}],matches:[],tags:["meinung"]},
  {id:"g-n4-janai-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜じゃないか – nicht wahr?, findest du nicht?",jp:"〜じゃないか／〜ではないか",summary:"Wird verwendet, wenn man Zustimmung vom Zuhörer erwartet, um Überraschung auszudrücken oder um zu tadeln. Höflich: じゃないですか; in der Schriftsprache: ではないか. Frauen sagen eher じゃない.",structure:["Kurzform + じゃないか","Nomen／な-Adjektiv + じゃないか"],examples:[{jp:"なかなかおいしいじゃないか。",de:"Das schmeckt ja ziemlich gut!",en:"This is pretty good, isn't it?"},{jp:"危[あぶ]ないじゃないですか。",de:"Das ist doch gefährlich!",en:"That is dangerous, you know!"}],matches:[],tags:["satzende"]},
  {id:"g-n4-kana",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かな – ich frage mich, ob",jp:"〜かな",summary:"Ein umgangssprachliches Satzende, mit dem man sich selbst eine Frage stellt oder eine weiche, indirekte Frage formuliert.",structure:["Kurzform + かな","Nomen／な-Adjektiv + かな"],examples:[{jp:"明日[あした]は晴[は]れるかな。",de:"Ob es morgen wohl sonnig wird?",en:"I wonder if it will be sunny tomorrow."}],matches:[],tags:["satzende","fragen","informell"]},
  {id:"g-n4-kashira",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かしら – ich frage mich, ob (feminin)",jp:"〜かしら",summary:"Bedeutet dasselbe wie かな, klingt aber feminin und etwas altmodisch.",structure:["Kurzform + かしら","Nomen／な-Adjektiv + かしら"],examples:[{jp:"この服[ふく]、私[わたし]に似合[にあ]うかしら。",de:"Ob mir dieses Kleidungsstück wohl steht?",en:"I wonder if these clothes suit me."}],matches:[],tags:["satzende","fragen"]},
  {id:"g-n4-kai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かい – umgangssprachliche Ja/Nein-Frage",jp:"〜かい",summary:"Ein weiches, freundliches Frageende für Ja/Nein-Fragen, das vor allem ältere Männer gegenüber Jüngeren verwenden. Bei Fragewörtern steht stattdessen だい.",structure:["Kurzform + かい","Nomen／な-Adjektiv + かい"],examples:[{jp:"元気[げんき]かい。",de:"Geht's dir gut?",en:"Are you well?"},{jp:"もう宿題[しゅくだい]は終[お]わったかい。",de:"Bist du schon fertig mit den Hausaufgaben?",en:"Have you finished your homework yet?"}],matches:[],tags:["satzende","fragen","informell"]},
  {id:"g-n4-you-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ように – damit, sodass",jp:"〜ように",summary:"Nennt das Ziel einer Handlung, wenn dieses Ziel ein Zustand ist, den man nicht direkt steuern kann: Potentialverben, わかる, みえる, verneinte Formen. (Für Handlungen, die man selbst steuert, verwendet man ために.)",structure:["Wörterbuchform (Potential) + ように","ない-Form + ように"],examples:[{jp:"後[うし]ろの人[ひと]にも聞[き]こえるように、大[おお]きい声[こえ]で話[はな]します。",de:"Ich spreche laut, damit es auch die Leute hinten hören können.",en:"I speak loudly so that the people at the back can hear, too."},{jp:"忘[わす]れないように、メモします。",de:"Ich mache mir eine Notiz, damit ich es nicht vergesse.",en:"I take notes so that I don't forget."}],matches:[],tags:["zweck"]},
  {id:"g-n4-you-ni-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようにする – darauf achten, sich bemühen zu",jp:"〜ようにする",summary:"Sagt, dass man sich bemüht, etwas regelmäßig zu tun (oder nicht zu tun). ようにしている ist eine Gewohnheit, die man beibehält; ようにしてください ist eine sanfte Bitte.",structure:["Wörterbuchform + ようにする","ない-Form + ようにする"],examples:[{jp:"毎日[まいにち]野菜[やさい]を食[た]べるようにしています。",de:"Ich achte darauf, jeden Tag Gemüse zu essen.",en:"I make sure to eat vegetables every day."},{jp:"授業[じゅぎょう]に遅[おく]れないようにしてください。",de:"Achten Sie bitte darauf, nicht zu spät zum Unterricht zu kommen.",en:"Please make sure you are not late for class."}],matches:[],tags:["gewohnheit","bemühung"]},
  {id:"g-n4-you-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ようになる – dahin kommen, inzwischen können",jp:"〜ようになる",summary:"Sagt, dass sich eine Fähigkeit oder Gewohnheit im Lauf der Zeit verändert hat: Was man früher nicht konnte oder nicht tat, tut man jetzt. Das Gegenteil ist 〜なくなる.",structure:["Wörterbuchform (oft Potential) + ようになる","ない-Form: 〜なくなる"],examples:[{jp:"日本語[にほんご]の新聞[しんぶん]が読[よ]めるようになりました。",de:"Ich kann inzwischen japanische Zeitungen lesen.",en:"I have become able to read Japanese newspapers."},{jp:"最近[さいきん]、早[はや]く起[お]きるようになりました。",de:"In letzter Zeit stehe ich früh auf (das war früher nicht so).",en:"Recently I have started getting up early."}],matches:[],tags:["veränderung"]},
  {id:"g-n4-koto-ni-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ことにする – beschließen zu",jp:"〜ことにする",summary:"Sagt, dass man selbst etwas beschließt. ことにしている bedeutet, dass man es sich zur Regel gemacht hat.",structure:["Wörterbuchform + ことにする","ない-Form + ことにする"],examples:[{jp:"来月[らいげつ]から水泳[すいえい]を習[なら]うことにしました。",de:"Ich habe beschlossen, ab nächstem Monat Schwimmunterricht zu nehmen.",en:"I have decided to take swimming lessons from next month."},{jp:"夜[よる]はコーヒーを飲[の]まないことにしています。",de:"Ich habe es mir zur Regel gemacht, abends keinen Kaffee zu trinken.",en:"I make it a rule not to drink coffee at night."}],matches:[],tags:["entscheidung"]},
  {id:"g-n4-koto-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ことになる – es wurde beschlossen, dass",jp:"〜ことになる",summary:"Sagt, dass etwas von anderen oder durch die Umstände entschieden wurde, nicht von einem selbst allein. ことになっている beschreibt eine Regel oder Abmachung.",structure:["Wörterbuchform + ことになる","ない-Form + ことになる"],examples:[{jp:"来年[らいねん]、大阪[おおさか]で働[はたら]くことになりました。",de:"Es hat sich ergeben, dass ich nächstes Jahr in Osaka arbeiten werde.",en:"It has been decided that I will work in Osaka next year."},{jp:"ここでは靴[くつ]を脱[ぬ]ぐことになっています。",de:"Hier zieht man die Schuhe aus (so ist die Regel).",en:"You are supposed to take off your shoes here."}],matches:[],tags:["entscheidung","regeln"]},
  {id:"g-n4-yotei-da",type:"grammar",source:"JLPT N4",level:"N4",title:"〜予定だ – geplant sein, vorhaben",jp:"〜よていだ",summary:"Spricht von einem festen Plan oder Termin. Es ist verbindlicher als つもりだ, das nur die eigene Absicht ausdrückt.",structure:["Wörterbuchform + よていだ","Nomen + の + よていだ"],examples:[{jp:"来週[らいしゅう]、出張[しゅっちょう]する予定[よてい]です。",de:"Nächste Woche ist eine Dienstreise für mich geplant.",en:"I am scheduled to go on a business trip next week."},{jp:"会議[かいぎ]は三時[さんじ]からの予定[よてい]です。",de:"Die Besprechung soll planmäßig um drei Uhr beginnen.",en:"The meeting is scheduled to start at three."}],matches:[],tags:["absicht","zukunft"]},
  {id:"g-n4-ku-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜くする／〜にする – etwas … machen",jp:"〜くする／〜にする",summary:"Adjektiv + する bedeutet, dass jemand etwas absichtlich verändert. (Vergleiche 〜くなる／〜になる, wo es sich von selbst verändert.)",structure:["い-Adjektiv: 〜く + する","な-Adjektiv／Nomen + に + する"],examples:[{jp:"部屋[へや]を明[あか]るくしました。",de:"Ich habe das Zimmer heller gemacht.",en:"I made the room brighter."},{jp:"教室[きょうしつ]では静[しず]かにしてください。",de:"Seien Sie im Klassenzimmer bitte leise.",en:"Please be quiet in the classroom."}],matches:[],tags:["adjektive","veränderung"]},
  {id:"g-n4-koto",type:"grammar",source:"JLPT N4",level:"N4",title:"こと – aus einem Verb ein Nomen machen",jp:"〜こと",summary:"Kurzform + こと macht aus einem Teilsatz eine Nominalphrase („das …-en“, „die Tatsache, dass …“). Es ist etwas förmlicher als の und steht vor です sowie in festen Mustern wie ことができる.",structure:["Kurzform + こと + は／が／を","Nomen は + Wörterbuchform + こと + です"],examples:[{jp:"私[わたし]の趣味[しゅみ]は写真[しゃしん]を撮[と]ることです。",de:"Mein Hobby ist Fotografieren.",en:"My hobby is taking photos."},{jp:"外国語[がいこくご]を習[なら]うことは楽[たの]しいです。",de:"Fremdsprachen zu lernen macht Spaß.",en:"Learning foreign languages is fun."}],matches:[],tags:["nominalisierung"]},
  {id:"g-n4-to-iu-koto",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ということ – die Tatsache, dass",jp:"〜ということ",summary:"Macht aus einer ganzen Aussage ein Nomen: „die Tatsache, dass …“, „dass …“. Es steht bei Verben wie しる, わかる, きく und わすれる. 〜ということだ am Satzende bedeutet „das heißt, dass …“ oder „ich höre, dass …“.",structure:["Kurzform + ということ"],examples:[{jp:"田中[たなか]さんが会社[かいしゃ]をやめたということを知[し]っていますか。",de:"Wissen Sie, dass Herr Tanaka in der Firma gekündigt hat?",en:"Do you know that Mr. Tanaka quit the company?"}],matches:[],tags:["nominalisierung","zitat"]},
  {id:"g-n4-to-iu",type:"grammar",source:"JLPT N4",level:"N4",title:"〜という／〜って – namens, genannt",jp:"A という B",summary:"A という B führt etwas ein, das der Zuhörer vielleicht nicht kennt: „ein B namens A“. In der Umgangssprache wird という zu って; って kann auch das zitierende と ersetzen („er hat gesagt, dass …“).",structure:["Name + という + Nomen","Umgangssprachlich: Name + って + Nomen","Kurzform + って (= と) + いう／きく"],examples:[{jp:"「さくら」という店[みせ]を知[し]っていますか。",de:"Kennen Sie ein Geschäft namens „Sakura“?",en:"Do you know a shop called \"Sakura\"?"},{jp:"山田[やまだ]さんは今日[きょう]来[こ]ないって言[い]っていたよ。",de:"Yamada hat gesagt, dass er heute nicht kommt.",en:"Yamada said he is not coming today."}],matches:[],tags:["zitat"]},
  {id:"g-n4-ka-dou-ka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜かどうか／Fragewort + か – ob; Fragen innerhalb eines Satzes",jp:"〜かどうか／〜か",summary:"Eine Frage lässt sich in einen längeren Satz einbetten. Eine Ja/Nein-Frage bekommt かどうか („ob oder ob nicht“); eine Frage mit Fragewort bekommt nur か. Vor か entfällt だ.",structure:["Kurzform + かどうか + しる／わかる／きく","Fragewort + Kurzform + か + しる／わかる／きく"],examples:[{jp:"明日[あした]行[い]けるかどうか、まだわかりません。",de:"Ich weiß noch nicht, ob ich morgen hingehen kann.",en:"I don't know yet whether I can go tomorrow."},{jp:"会議[かいぎ]が何時[なんじ]に始[はじ]まるか教[おし]えてください。",de:"Sagen Sie mir bitte, um wie viel Uhr die Besprechung beginnt.",en:"Please tell me what time the meeting starts."}],matches:[],tags:["fragen","nebensatz"]},
  {id:"g-n4-sa",type:"grammar",source:"JLPT N4",level:"N4",title:"〜さ – aus einem Adjektiv ein Nomen machen",jp:"〜さ",summary:"Ersetzt man das auslautende い eines い-Adjektivs durch さ (oder hängt さ an ein な-Adjektiv an), entsteht ein Nomen für eine messbare Eigenschaft: „-heit/-keit“, „wie … etwas ist“. いい wird zu よさ.",structure:["い-Adjektiv ohne い + さ","な-Adjektiv + さ"],examples:[{jp:"この山[やま]の高[たか]さはどのくらいですか。",de:"Wie hoch ist dieser Berg?",en:"How high is this mountain?"},{jp:"家族[かぞく]の大切[たいせつ]さがわかりました。",de:"Ich habe begriffen, wie wichtig die Familie ist.",en:"I came to understand how important family is."}],matches:[],tags:["adjektive","nomen","nominalisierung"]},
  {id:"g-n4-nakereba-naranai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なければならない／〜なければいけない – müssen",jp:"〜なければならない／〜なければいけない",summary:"ない-Form ohne い + ければならない bedeutet „müssen“. ならない klingt nach einer allgemeinen Regel oder Pflicht, いけない ist persönlicher; beide sind gebräuchlich. In der Umgangssprache wird es zu なきゃ verkürzt.",structure:["ない-Form: 〜なければ + ならない","ない-Form: 〜なければ + いけない"],examples:[{jp:"明日[あした]までにレポートを出[だ]さなければなりません。",de:"Ich muss den Bericht bis morgen abgeben.",en:"I have to hand in the report by tomorrow."},{jp:"もう帰[かえ]らなければいけません。",de:"Ich muss jetzt nach Hause gehen.",en:"I have to go home now."}],matches:["g-g12-nakereba"],tags:["pflicht","müssen"]},
  {id:"g-n4-nakute-mo-ii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜なくてもいい – nicht müssen",jp:"〜なくてもいい",summary:"ない-Form ohne い + くてもいい sagt, dass etwas nicht nötig ist.",structure:["ない-Form: 〜なくても + いい"],examples:[{jp:"明日[あした]は来[こ]なくてもいいです。",de:"Morgen brauchen Sie nicht zu kommen.",en:"You don't have to come tomorrow."}],matches:[],tags:["pflicht","erlaubnis"]},
  {id:"g-n4-naide",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ないで – ohne zu tun; statt zu tun",jp:"〜ないで",summary:"ない-Form + で verbindet zwei Handlungen: Man tut B, ohne A zu tun, oder man tut B statt A.",structure:["ない-Form + で + Haupthandlung"],examples:[{jp:"朝[あさ]ご飯[はん]を食[た]べないで学校[がっこう]に行[い]きました。",de:"Ich bin zur Schule gegangen, ohne zu frühstücken.",en:"I went to school without eating breakfast."},{jp:"バスに乗[の]らないで、歩[ある]いて帰[かえ]りましょう。",de:"Lassen Sie uns nicht den Bus nehmen, sondern zu Fuß nach Hause gehen.",en:"Let's walk home instead of taking the bus."}],matches:[],tags:["verneinung","te-form"]},
  {id:"g-n4-ga-hitsuyou",type:"grammar",source:"JLPT N4",level:"N4",title:"〜が必要だ – brauchen",jp:"〜がひつようだ",summary:"ひつよう ist ein な-Adjektiv in der Bedeutung „notwendig“. Das, was gebraucht wird, wird mit が markiert, die Person oder der Zweck mit に.",structure:["Nomen + が + ひつようだ","Nomen + に + Nomen + が + ひつようだ","Wörterbuchform + のに + Nomen + が + ひつようだ"],examples:[{jp:"外国[がいこく]に行[い]くのにパスポートが必要[ひつよう]です。",de:"Um ins Ausland zu reisen, braucht man einen Reisepass.",en:"You need a passport to go abroad."}],matches:[],tags:["notwendigkeit"]},
  {id:"g-n4-hitsuyou-ga-aru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜必要がある – es ist nötig zu",jp:"〜ひつようがある",summary:"Wörterbuchform + 必要がある sagt, dass eine Handlung notwendig ist. Die Verneinung 〜必要はない bedeutet „es ist nicht nötig zu“.",structure:["Wörterbuchform + ひつようがある","Wörterbuchform + ひつようはない"],examples:[{jp:"もう一度[いちど]調[しら]べる必要[ひつよう]があります。",de:"Es ist nötig, das noch einmal zu überprüfen.",en:"It is necessary to check once more."},{jp:"急[いそ]ぐ必要[ひつよう]はありません。",de:"Es besteht kein Grund zur Eile.",en:"There is no need to hurry."}],matches:[],tags:["notwendigkeit"]},
  {id:"g-n4-ga-hoshii",type:"grammar",source:"JLPT N4",level:"N4",title:"〜がほしい – (eine Sache) haben wollen",jp:"〜がほしい",summary:"ほしい ist ein い-Adjektiv dafür, dass man eine Sache haben möchte; die Sache wird mit が markiert. Es gilt für die eigenen Wünsche (bei anderen Personen: ほしがっている).",structure:["Nomen + が + ほしい"],examples:[{jp:"新[あたら]しい自転車[じてんしゃ]がほしいです。",de:"Ich möchte ein neues Fahrrad haben.",en:"I want a new bicycle."}],matches:[],tags:["wunsch"]},
  {id:"g-n4-o-ni-naru",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜になる – ehrerbietige Verbform",jp:"お〜になる",summary:"お + Verbstamm + になる erhöht die Handlungen einer Person, der man Respekt entgegenbringt (Kunde, Lehrer, Vorgesetzter). Für die eigenen Handlungen verwendet man es nie. Verben, die eine eigene ehrerbietige Form haben (いらっしゃる, めしあがる …), nehmen stattdessen diese.",structure:["お + Verbstamm + になる"],examples:[{jp:"先生[せんせい]はもうお帰[かえ]りになりました。",de:"Der Lehrer ist bereits nach Hause gegangen.",en:"The teacher has already gone home."}],matches:[],tags:["keigo","ehrerbietig"]},
  {id:"g-n4-o-kudasai",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜ください – bitte tun Sie (ehrerbietig)",jp:"お〜ください",summary:"Eine respektvolle Bitte, die man oft in Geschäften, an Bahnhöfen und in Durchsagen hört. する-Nomen bekommen ご: ご〜ください.",structure:["お + Verbstamm + ください","ご + する-Nomen + ください"],examples:[{jp:"こちらで少々[しょうしょう]お待[ま]ちください。",de:"Bitte warten Sie hier einen Augenblick.",en:"Please wait here a moment."},{jp:"ご注意[ちゅうい]ください。",de:"Bitte geben Sie acht.",en:"Please be careful."}],matches:[],tags:["keigo","bitte"]},
  {id:"g-n4-irassharu",type:"grammar",source:"JLPT N4",level:"N4",title:"いらっしゃる – sein, gehen, kommen (ehrerbietig)",jp:"いらっしゃる",summary:"Das ehrerbietige Verb für いる, いく und くる. Seine ます-Form ist unregelmäßig: いらっしゃいます. 〜ていらっしゃる ist die ehrerbietige Entsprechung von 〜ている.",structure:["いる／いく／くる → いらっしゃる","て-Form + いらっしゃる"],examples:[{jp:"社長[しゃちょう]は今[いま]、会議室[かいぎしつ]にいらっしゃいます。",de:"Der Firmenchef ist gerade im Besprechungsraum.",en:"The company president is in the meeting room now."},{jp:"明日[あした]は何時[なんじ]にいらっしゃいますか。",de:"Um wie viel Uhr kommen Sie morgen?",en:"What time will you come tomorrow?"}],matches:[],tags:["keigo","ehrerbietig"]},
  {id:"g-n4-nasaru",type:"grammar",source:"JLPT N4",level:"N4",title:"なさる – tun (ehrerbietig)",jp:"なさる",summary:"Das ehrerbietige Verb für する. Seine ます-Form ist unregelmäßig: なさいます.",structure:["する → なさる","する-Nomen + なさる"],examples:[{jp:"先生[せんせい]は何[なに]を研究[けんきゅう]なさっていますか。",de:"Woran forschen Sie, Herr Professor?",en:"What are you researching, professor?"},{jp:"お飲[の]み物[もの]は何[なに]になさいますか。",de:"Was möchten Sie trinken?",en:"What would you like to drink?"}],matches:[],tags:["keigo","ehrerbietig"]},
  {id:"g-n4-gozaimasu",type:"grammar",source:"JLPT N4",level:"N4",title:"ございます – es gibt, haben (sehr höflich)",jp:"ございます",summary:"Die sehr höfliche Form von あります, die man gegenüber Kunden und in förmlichen Situationen verwendet.",structure:["Nomen + が／は + ございます"],examples:[{jp:"お手洗[てあら]いは二階[にかい]にございます。",de:"Die Toilette befindet sich im ersten Stock.",en:"The restroom is on the second floor."}],matches:[],tags:["keigo","höflich","existenz"]},
  {id:"g-n4-de-gozaimasu",type:"grammar",source:"JLPT N4",level:"N4",title:"でございます – sein (sehr höflich)",jp:"〜でございます",summary:"Die sehr höfliche Form von です, die Angestellte gegenüber Kunden sowie in Bezug auf sich selbst oder die eigene Seite verwenden.",structure:["Nomen + でございます"],examples:[{jp:"こちらが新[あたら]しい商品[しょうひん]でございます。",de:"Dies hier ist unser neues Produkt.",en:"This is our new product."}],matches:[],tags:["keigo","höflich","kopula"]},
  {id:"g-n4-itasu",type:"grammar",source:"JLPT N4",level:"N4",title:"いたす – tun (bescheiden)",jp:"いたす／いたします",summary:"Das bescheidene Verb für する: Man setzt die eigene Handlung herab, um Respekt zu zeigen. Es wird fast immer als いたします verwendet.",structure:["する → いたす","お + Verbstamm + いたします"],examples:[{jp:"よろしくお願[ねが]いいたします。",de:"Vielen Dank im Voraus. / Ich bitte um Ihr Wohlwollen.",en:"Thank you in advance. / I am in your hands."},{jp:"後[あと]でお電話[でんわ]いたします。",de:"Ich rufe Sie später an.",en:"I will call you later."}],matches:[],tags:["keigo","bescheiden"]},
  {id:"g-n4-o-suru",type:"grammar",source:"JLPT N4",level:"N4",title:"お〜する – bescheidene Verbform",jp:"お〜する",summary:"お + Verbstamm + する beschreibt etwas, das man für eine Person tut, der man Respekt entgegenbringt. する-Nomen bekommen ご. Noch bescheidener: お〜いたします.",structure:["お + Verbstamm + する","ご + する-Nomen + する"],examples:[{jp:"荷物[にもつ]をお持[も]ちしましょうか。",de:"Soll ich Ihr Gepäck tragen?",en:"Shall I carry your luggage?"},{jp:"駅[えき]までご案内[あんない]します。",de:"Ich begleite Sie bis zum Bahnhof.",en:"I will show you the way to the station."}],matches:[],tags:["keigo","bescheiden"]},
  {id:"g-n4-shi",type:"grammar",source:"JLPT N4",level:"N4",title:"〜し – und außerdem; Gründe aufzählen",jp:"〜し、〜し",summary:"し nach der Kurzform zählt mehrere Tatsachen oder Gründe auf und deutet an, dass es noch weitere gibt.",structure:["Kurzform + し、Kurzform + し、…"],examples:[{jp:"このアパートは駅[えき]に近[ちか]いし、家賃[やちん]も安[やす]いです。",de:"Diese Wohnung liegt nah am Bahnhof, und die Miete ist auch günstig.",en:"This apartment is close to the station, and the rent is cheap, too."},{jp:"雨[あめ]だし、疲[つか]れたし、今日[きょう]は出[で]かけません。",de:"Es regnet, ich bin müde – heute gehe ich nicht aus.",en:"It is raining and I am tired, so I am not going out today."}],matches:[],tags:["partikel","grund","aufzählung"]},
  {id:"g-n4-toka-toka",type:"grammar",source:"JLPT N4",level:"N4",title:"〜とか〜とか – so etwas wie … oder …",jp:"〜とか〜とか",summary:"Eine umgangssprachliche Art, Beispiele aus einer längeren Liste zu nennen. Es kann auf Nomen und auf Verben in der Kurzform folgen.",structure:["Nomen + とか + Nomen + とか","Wörterbuchform + とか + Wörterbuchform + とか"],examples:[{jp:"休[やす]みの日[ひ]は掃除[そうじ]とか洗濯[せんたく]とかをします。",de:"An freien Tagen mache ich Dinge wie Putzen oder Wäschewaschen.",en:"On my days off I do things like cleaning and laundry."}],matches:["g-g11-toka"],tags:["partikel","aufzählung","informell"]},
  {id:"g-n4-nado",type:"grammar",source:"JLPT N4",level:"N4",title:"〜など – wie zum Beispiel, und so weiter",jp:"〜など",summary:"など nach einem Nomen (oft nach einer Aufzählung mit や) zeigt, dass es sich nur um Beispiele handelt. Es ist förmlicher als とか.",structure:["Nomen (や Nomen) + など"],examples:[{jp:"かばんの中[なか]に本[ほん]やノートなどがあります。",de:"In der Tasche sind Bücher, Hefte und so weiter.",en:"In my bag there are books, notebooks and so on."}],matches:[],tags:["partikel","aufzählung"]},
  {id:"g-n4-demo",type:"grammar",source:"JLPT N4",level:"N4",title:"〜でも – … oder so",jp:"〜でも",summary:"でも nach einem Nomen macht einen Vorschlag weicher, indem es nur ein Beispiel nennt: „… oder so etwas“. Nach einem Fragewort bedeutet es „egal/jede(r, s)“: なんでも (alles, egal was), いつでも (jederzeit).",structure:["Nomen + でも","Fragewort + でも"],examples:[{jp:"お茶[ちゃ]でも飲[の]みませんか。",de:"Wollen wir einen Tee oder so trinken?",en:"Shall we have some tea or something?"},{jp:"いつでも電話[でんわ]してください。",de:"Rufen Sie mich bitte jederzeit an.",en:"Please call me any time."}],matches:[],tags:["partikel","vorschlag","unbestimmt"]},
  {id:"g-n4-shika-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"〜しか〜ない – nur, nichts als",jp:"〜しか〜ない",summary:"しか steht immer mit einem verneinten Verb und bedeutet „nur“ – mit dem Gefühl, dass es weniger als erwartet oder nicht genug ist. しか ersetzt が und を.",structure:["Nomen／Zahl + しか + verneintes Verb"],examples:[{jp:"財布[さいふ]に百円[ひゃくえん]しかありません。",de:"Ich habe nur 100 Yen im Portemonnaie.",en:"I have only 100 yen in my wallet."},{jp:"昨日[きのう]は三時間[さんじかん]しか寝[ね]ませんでした。",de:"Gestern habe ich nur drei Stunden geschlafen.",en:"I slept only three hours last night."}],matches:[],tags:["partikel","menge","verneinung"]},
  {id:"g-n4-mo-amount",type:"grammar",source:"JLPT N4",level:"N4",title:"Zahl + も – ganze …, sogar so viel wie",jp:"Number + も",summary:"も nach einer Zahl oder Menge zeigt, dass der Sprecher sie als viel empfindet. Zusammen mit einem verneinten Verb und „eins“ (ひとつも, いちども) bedeutet es „nicht ein einziges“.",structure:["Zahl + Zähler + も","ひとつ／いちど + も + verneintes Verb"],examples:[{jp:"昨日[きのう]は十時間[じゅうじかん]も寝[ね]ました。",de:"Gestern habe ich ganze zehn Stunden geschlafen.",en:"I slept as much as ten hours yesterday."},{jp:"納豆[なっとう]は一度[いちど]も食[た]べたことがありません。",de:"Natto habe ich noch nie gegessen, nicht ein einziges Mal.",en:"I have never eaten natto, not even once."}],matches:[],tags:["partikel","menge","zähler"]},
  {id:"g-n4-bakari",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ばかり – nichts als, immer nur",jp:"〜ばかり",summary:"ばかり nach einem Nomen oder der て-Form sagt, dass es nur das gibt oder jemand nur das tut, und zwar zu viel davon – meist eine Beschwerde.",structure:["Nomen + ばかり","て-Form + ばかり + いる"],examples:[{jp:"弟[おとうと]は肉[にく]ばかり食[た]べます。",de:"Mein jüngerer Bruder isst immer nur Fleisch.",en:"My younger brother eats nothing but meat."},{jp:"息子[むすこ]はゲームをしてばかりいます。",de:"Mein Sohn spielt immer nur Videospiele.",en:"My son does nothing but play video games."}],matches:[],tags:["partikel"]},
  {id:"g-n4-dake-de",type:"grammar",source:"JLPT N4",level:"N4",title:"〜だけで – allein durch, nur mit",jp:"〜だけで",summary:"だけ („nur“) + で: Etwas genügt schon oder geschieht allein dadurch.",structure:["Wörterbuchform／た-Form + だけで","Nomen + だけで"],examples:[{jp:"このボタンを押[お]すだけで、写真[しゃしん]が撮[と]れます。",de:"Man braucht nur diesen Knopf zu drücken, schon kann man ein Foto machen.",en:"You can take a photo just by pressing this button."},{jp:"見[み]ているだけで楽[たの]しいです。",de:"Schon das Zuschauen macht Spaß.",en:"It is fun just to watch."}],matches:[],tags:["partikel"]},
  {id:"g-n4-kara-tsukuru",type:"grammar",source:"JLPT N4",level:"N4",title:"〜から作る／〜で作る – hergestellt aus",jp:"〜からつくる／〜でつくる",summary:"から markiert einen Rohstoff, der sich völlig verändert und nicht mehr zu erkennen ist; で markiert ein Material, das man noch erkennen kann. Dasselbe gilt für できる („hergestellt werden“).",structure:["Rohstoff + から + つくる／できる","Material + で + つくる／できる"],examples:[{jp:"ワインはぶどうから作[つく]られます。",de:"Wein wird aus Trauben hergestellt.",en:"Wine is made from grapes."},{jp:"この机[つくえ]は木[き]でできています。",de:"Dieser Schreibtisch ist aus Holz.",en:"This desk is made of wood."}],matches:[],tags:["partikel","material"]},
  {id:"g-n4-ni-ki-ga-tsuku",type:"grammar",source:"JLPT N4",level:"N4",title:"〜に気がつく – bemerken, merken",jp:"〜にきがつく",summary:"Sagt, dass einem etwas bewusst wird. Ein Teilsatz wird zuvor mit の oder こと zu einem Nomen gemacht.",structure:["Nomen + に + きがつく","Kurzform + の／こと + に + きがつく"],examples:[{jp:"家[いえ]を出[で]てから、忘[わす]れ物[もの]に気[き]がつきました。",de:"Nachdem ich aus dem Haus gegangen war, bemerkte ich, dass ich etwas vergessen hatte.",en:"After leaving the house, I noticed I had forgotten something."},{jp:"財布[さいふ]がないことに気[き]がつきました。",de:"Ich habe gemerkt, dass mein Portemonnaie weg ist.",en:"I realized that my wallet was gone."}],matches:[],tags:["ausdruck"]},
  {id:"g-n4-toki",type:"grammar",source:"JLPT N4",level:"N4",title:"〜とき – als, wenn",jp:"〜とき",summary:"Ein Teilsatz + とき gibt die Zeit der Haupthandlung an. Die Zeitform vor とき ist relativ: Wörterbuchform = die Haupthandlung geschieht, bevor jene Handlung abgeschlossen ist; Vergangenheitsform = nachdem sie abgeschlossen ist.",structure:["Kurzform + とき","Nomen + の + とき","な-Adjektiv + な + とき"],examples:[{jp:"日本[にほん]に行[い]くとき、かばんを買[か]いました。",de:"Als ich nach Japan fuhr, habe ich (vor der Abreise) eine Tasche gekauft.",en:"I bought a bag when I was going to Japan (before leaving)."},{jp:"子[こ]どものとき、よく川[かわ]で遊[あそ]びました。",de:"Als Kind habe ich oft am Fluss gespielt.",en:"When I was a child, I often played in the river."}],matches:[],tags:["zeit"]},
  {id:"g-n4-aida-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜間／〜間に – während",jp:"〜あいだ／〜あいだに",summary:"あいだ bedeutet „die ganze Zeit über“: Die Haupthandlung dauert währenddessen durchgehend an. あいだに bedeutet „irgendwann innerhalb dieser Zeit“: Die Haupthandlung geschieht einmal und ist abgeschlossen, bevor die Zeit endet.",structure:["て-Form + いる + あいだ(に)","Nomen + の + あいだ(に)"],examples:[{jp:"子[こ]どもが寝[ね]ている間[あいだ]に、買[か]い物[もの]に行[い]きました。",de:"Während das Kind schlief, bin ich einkaufen gegangen.",en:"I went shopping while the child was sleeping."},{jp:"夏休[なつやす]みの間[あいだ]、ずっと祖母[そぼ]の家[いえ]にいました。",de:"Während der Sommerferien war ich die ganze Zeit bei meiner Großmutter.",en:"I stayed at my grandmother's house all through the summer holidays."}],matches:[],tags:["zeit","dauer"]},
  {id:"g-n4-ato-de",type:"grammar",source:"JLPT N4",level:"N4",title:"〜後で – nachdem, nach",jp:"〜あとで",summary:"Sagt, dass B nach A geschieht. Das Verb vor あとで steht immer in der た-Form, auch wenn von der Zukunft die Rede ist.",structure:["た-Form + あとで","Nomen + の + あとで"],examples:[{jp:"ご飯[はん]を食[た]べた後[あと]で、薬[くすり]を飲[の]みます。",de:"Ich nehme das Medikament nach dem Essen.",en:"I take the medicine after eating."},{jp:"授業[じゅぎょう]の後[あと]で、図書館[としょかん]に行[い]きます。",de:"Nach dem Unterricht gehe ich in die Bibliothek.",en:"After class I am going to the library."}],matches:[],tags:["zeit"]},
  {id:"g-n4-made-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜までに – bis spätestens (Frist)",jp:"〜までに",summary:"までに nennt eine Frist: Die Handlung muss vor diesem Zeitpunkt abgeschlossen sein. (まで allein bedeutet, dass die Handlung bis dahin andauert.)",structure:["Zeitangabe + までに","Wörterbuchform + までに"],examples:[{jp:"金曜日[きんようび]までに宿題[しゅくだい]を出[だ]してください。",de:"Geben Sie die Hausaufgaben bitte bis Freitag ab.",en:"Please hand in your homework by Friday."}],matches:[],tags:["partikel","zeit"]},
  {id:"g-n4-goro",type:"grammar",source:"JLPT N4",level:"N4",title:"〜ごろ – ungefähr um (Zeitpunkt)",jp:"〜ごろ",summary:"ごろ nach einem Zeitpunkt bedeutet „ungefähr um“. Für Mengen und Zeitspannen verwendet man stattdessen くらい／ぐらい.",structure:["Zeitpunkt + ごろ"],examples:[{jp:"毎晩[まいばん]十一時[じゅういちじ]ごろ寝[ね]ます。",de:"Ich gehe jeden Abend gegen elf Uhr ins Bett.",en:"I go to bed at around eleven every night."}],matches:[],tags:["zeit","uhrzeit"]},
  {id:"g-n4-oki-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"〜おきに – jeden zweiten, im Abstand von",jp:"〜おきに",summary:"Zahl + Zähler + おきに sagt, dass sich etwas mit diesem Abstand dazwischen wiederholt. Achtung: いちにちおきに bedeutet „jeden zweiten Tag“.",structure:["Zahl + Zähler + おきに"],examples:[{jp:"バスは十分[じゅっぷん]おきに来[き]ます。",de:"Der Bus kommt alle zehn Minuten.",en:"The bus comes every ten minutes."},{jp:"一日[いちにち]おきにジムに行[い]きます。",de:"Ich gehe jeden zweiten Tag ins Fitnessstudio.",en:"I go to the gym every other day."}],matches:[],tags:["zeit","häufigkeit"]},
  {id:"g-n4-amari-nai",type:"grammar",source:"JLPT N4",level:"N4",title:"あまり〜ない – nicht besonders, nicht viel",jp:"あまり〜ない",summary:"あまり zusammen mit einem verneinten Verb oder Adjektiv bedeutet „nicht besonders“ oder „nicht oft“. In der Umgangssprache wird es zu あんまり.",structure:["あまり + verneintes Verb／Adjektiv"],examples:[{jp:"この映画[えいが]はあまりおもしろくないです。",de:"Dieser Film ist nicht besonders interessant.",en:"This movie is not very interesting."},{jp:"私[わたし]はあまりテレビを見[み]ません。",de:"Ich sehe nicht viel fern.",en:"I don't watch much TV."}],matches:["g-g3-frequency"],tags:["adverbien","verneinung"]},
  {id:"g-n4-zenzen",type:"grammar",source:"JLPT N4",level:"N4",title:"全然〜ない – überhaupt nicht",jp:"ぜんぜん〜ない",summary:"ぜんぜん zusammen mit einem verneinten Verb oder Adjektiv bedeutet „überhaupt nicht“.",structure:["ぜんぜん + verneintes Verb／Adjektiv"],examples:[{jp:"中国語[ちゅうごくご]は全然[ぜんぜん]わかりません。",de:"Chinesisch verstehe ich überhaupt nicht.",en:"I don't understand Chinese at all."}],matches:["g-g3-frequency"],tags:["adverbien","verneinung"]},
  {id:"g-n4-sonna-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"そんなに – so sehr, so viel",jp:"そんなに",summary:"Bezieht sich auf ein Ausmaß, das gerade erwähnt wurde oder das man sehen kann. Zusammen mit einer Verneinung bedeutet es „nicht so …“.",structure:["そんなに + Verb／Adjektiv","そんなに + Verneinung"],examples:[{jp:"そんなに食[た]べたら、おなかが痛[いた]くなりますよ。",de:"Wenn Sie so viel essen, bekommen Sie Bauchschmerzen.",en:"If you eat that much, you will get a stomachache."},{jp:"この店[みせ]はそんなに高[たか]くないです。",de:"Dieses Geschäft ist gar nicht so teuer.",en:"This shop is not that expensive."}],matches:[],tags:["adverbien"]},
  {id:"g-n4-sore-ni",type:"grammar",source:"JLPT N4",level:"N4",title:"それに – außerdem, obendrein",jp:"それに",summary:"Leitet einen Satz ein, der dem gerade Gesagten einen weiteren Punkt derselben Art hinzufügt.",structure:["Satz A。それに、Satz B。"],examples:[{jp:"この部屋[へや]は広[ひろ]いです。それに、駅[えき]からも近[ちか]いです。",de:"Dieses Zimmer ist geräumig. Außerdem ist es auch nicht weit vom Bahnhof.",en:"This room is spacious. Besides, it is close to the station."}],matches:[],tags:["konjunktion","satzverbindung"]},
  {id:"g-n4-sore-demo",type:"grammar",source:"JLPT N4",level:"N4",title:"それでも – trotzdem, dennoch",jp:"それでも",summary:"Leitet einen Satz ein, der trotz des gerade Gesagten zutrifft.",structure:["Satz A。それでも、Satz B。"],examples:[{jp:"何度[なんど]も失敗[しっぱい]しました。それでも、あきらめませんでした。",de:"Ich bin viele Male gescheitert. Trotzdem habe ich nicht aufgegeben.",en:"I failed many times. Even so, I did not give up."}],matches:[],tags:["konjunktion","satzverbindung"]},
];
